+.item {
+  margin: 0 0 18px;
+  padding-left: var(--x, 0px);
+}
+
+/* 도장과 카드가 함께 한 링크다. */
+.stop {
+  display: grid;
+  grid-template-columns: 48px minmax(0, 1fr);
+  column-gap: 20px;
+  align-items: center;
+  min-height: 72px;
+  border-radius: 14px;
+  color: inherit;
+  text-decoration: none;
+}
+
+.stop:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: 3px;
+}
+
+.node {
+  position: relative;
+  display: block;
+  width: 48px;
+  height: 48px;
+  transition: transform 0.15s cubic-bezier(0.2, 0, 0, 1);
+}
+
+.node svg {
+  width: 100%;
+  height: 100%;
+  filter: drop-shadow(0 6px 8px rgb(0 0 0 / 50%));
+}
+
+.narrow {
+  display: none !important;
+}
+
+.stop:hover .node,
+.stop:focus-visible .node {
+  transform: translateY(-2px);
+}
+
+.card {
+  display: block;
+  min-width: 0;
+  padding: 12px 16px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 12px;
+  background: rgb(22 25 24 / 92%);
+  transition: border-color 0.15s cubic-bezier(0.2, 0, 0, 1);
+}
+
+.stop:hover .card,
+.stop:focus-visible .card {
+  border-color: var(--thorp-line-strong);
+}
+
+/* 지금 이어 읽을 글: 한 화면에서 빛나는 곳 두 곳 가운데 하나다(design-notes §2). */
+.current .card {
+  border-color: rgb(47 220 122 / 45%);
+  background: linear-gradient(90deg, rgb(3 199 90 / 9%), transparent 65%), var(--thorp-surface);
+  box-shadow: 0 0 0 4px rgb(3 199 90 / 6%);
+}
+
+.main {
+  display: block;
+  min-width: 0;
+}
+
+.number {
+  display: block;
+  color: var(--thorp-muted);
+  font-family: var(--thorp-font-display, inherit);
+  font-size: 0.75rem;
+  font-weight: 700;
+  letter-spacing: 0.02em;
+  line-height: 1.2;
+}
+
+.title {
+  display: block;
+  margin-top: 3px;
+  font-size: 1rem;
+  font-weight: 650;
+  line-height: 1.4;
+  text-wrap: balance;
+  transition: color 0.15s cubic-bezier(0.2, 0, 0, 1);
+}
+
+.stop:hover .title,
+.stop:focus-visible .title {
+  color: var(--thorp-accent-soft);
+}
+
+.question {
+  display: block;
+  margin-top: 2px;
+  color: var(--thorp-copy);
+  font-size: 0.875rem;
+  line-height: 1.5;
+}
+
+/* 지금 이어 읽을 글의 '이어서 읽기 →'. 꼬리표 줄의 오른쪽 끝에 둔다(목업 .go-hint). */
+.hint {
+  display: inline-flex;
+  align-items: center;
+  gap: 4px;
+  margin-left: auto;
+  color: var(--thorp-accent-soft);
+  font-size: 0.8rem;
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+@media (min-width: 1024px) {
+  .card {
+    display: grid;
+    grid-template-columns: minmax(0, 1fr) 262px;
+    column-gap: 24px;
+    align-items: center;
+  }
+
+  .chips {
+    display: grid;
+    grid-template-columns: 112px 56px 70px;
+    gap: 8px;
+    justify-content: end;
+    justify-items: start;
+    margin-top: 0;
+  }
+
+  .chipsGuest {
+    grid-template-columns: 56px 70px;
+  }
+
+  .hint {
+    grid-column: 1 / -1;
+    justify-self: end;
+    margin: 0;
+  }
+}
+
+@media (max-width: 719px) {
+  .item {
+    margin-bottom: 16px;
+    padding-left: 0;
+  }
+
+  .stop {
+    grid-template-columns: 40px minmax(0, 1fr);
+    column-gap: 12px;
+  }
+
+  .node {
+    width: 40px;
+    height: 40px;
+  }
+
+  .wide {
+    display: none !important;
+  }
+
+  .narrow {
+    display: block !important;
+  }
+
+  .card {
+    padding: 10px 12px;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .node,
+  .card,
+  .title {
+    transition: none;
+  }
+
+  .stop:hover .node,
+  .stop:focus-visible .node {
+    transform: none;
+  }
+}

